"use strict";(self.webpackChunk_=self.webpackChunk_||[]).push([["745"],{5293(e){e.exports=JSON.parse('{"version":{"pluginId":"default","version":"current","label":"Next","banner":null,"badge":false,"noIndex":false,"className":"docs-version-current","isLast":true,"docsSidebars":{"docsSidebar":[{"type":"category","label":"Introduction","collapsed":false,"items":[{"type":"link","href":"/docs/what-is-kaiden","label":"What is Kaiden?","docId":"what-is-kaiden","unlisted":false},{"type":"link","href":"/docs/core-concepts","label":"Core Concepts","docId":"core-concepts","unlisted":false}],"collapsible":true},{"type":"category","label":"Getting Started","collapsed":false,"items":[{"type":"link","href":"/docs/installation","label":"Installation","docId":"installation","unlisted":false},{"type":"link","href":"/docs/your-first-sandbox","label":"Your First Sandbox","docId":"your-first-sandbox","unlisted":false}],"collapsible":true},{"type":"category","label":"Configuration","collapsed":false,"items":[{"type":"link","href":"/docs/models-and-inference","label":"Models & Inference","docId":"models-and-inference","unlisted":false},{"type":"link","href":"/docs/ai-agents","label":"AI Agents","docId":"ai-agents","unlisted":false},{"type":"link","href":"/docs/credentials-and-secrets","label":"Credentials & Secrets","docId":"credentials-and-secrets","unlisted":false},{"type":"link","href":"/docs/skills-mcp-knowledge","label":"Skills, MCP & Knowledge","docId":"skills-mcp-knowledge","unlisted":false}],"collapsible":true},{"type":"category","label":"Organizing Work","collapsed":false,"items":[{"type":"link","href":"/docs/projects","label":"Projects","docId":"projects","unlisted":false}],"collapsible":true},{"type":"category","label":"Security","collapsed":false,"items":[{"type":"link","href":"/docs/network-security","label":"Network Security","docId":"network-security","unlisted":false}],"collapsible":true},{"type":"category","label":"Reference","collapsed":false,"items":[{"type":"link","href":"/docs/openshell-gateways","label":"OpenShell Gateways","docId":"openshell-gateways","unlisted":false}],"collapsible":true},{"type":"category","label":"Settings","collapsed":false,"items":[{"type":"link","href":"/docs/settings","label":"Settings","docId":"settings","unlisted":false}],"collapsible":true}]},"docs":{"ai-agents":{"id":"ai-agents","title":"AI Agents","description":"AI coding agents are powerful \u2014 but running them directly on your machine means they operate with your full user permissions, your credentials, and unrestricted access to your filesystem and network. Kaiden changes that: every agent runs inside a secured sandbox, so you get the productivity benefits without the risk.","sidebar":"docsSidebar"},"core-concepts":{"id":"core-concepts","title":"Core Concepts","description":"This page explains the fundamental building blocks of Kaiden. Understanding these makes the rest of the application easier to navigate.","sidebar":"docsSidebar"},"credentials-and-secrets":{"id":"credentials-and-secrets","title":"Credentials & Secrets","description":"The Secret Vault is where you store every credential Kaiden needs to give your sandboxes authenticated access to external services.","sidebar":"docsSidebar"},"installation":{"id":"installation","title":"Installation","description":"Kaiden is a desktop application available for macOS, Windows, and Linux. The kdn and OpenShell CLI tools it depends on are downloaded and managed from inside the app \u2014 you don\'t install them separately.","sidebar":"docsSidebar"},"models-and-inference":{"id":"models-and-inference","title":"Models & Inference","description":"The Models section is the single place where you configure every model your coding agents can use. Whether you\'re running cloud APIs, local models on your laptop, or models hosted on an enterprise cluster \u2014 you connect them here once, and every agent across every sandbox can use them.","sidebar":"docsSidebar"},"network-security":{"id":"network-security","title":"Network Security","description":"Every Kaiden sandbox runs with a deny-by-default network policy. The agent cannot reach any host on the internet unless it has been explicitly allowed. This page explains how that policy works and how to configure it.","sidebar":"docsSidebar"},"openshell-gateways":{"id":"openshell-gateways","title":"OpenShell Gateways","description":"The gateway is the control plane of OpenShell. Every CLI command, SDK call, and UI interaction goes through it. It owns all durable platform state \u2014 sandboxes, policy revisions, provider credentials, inference configuration, and SSH sessions \u2014 and it coordinates the sandbox supervisor processes that run inside each agent environment.","sidebar":"docsSidebar"},"projects":{"id":"projects","title":"Projects","description":"A project is a codebase and its configuration. It captures the working directory, which credentials are available, what the network policy allows, and which skills, MCP servers, and knowledge bases the agent should use. Everything you configure at the project level is inherited by every sandbox and session you create under it.","sidebar":"docsSidebar"},"settings":{"id":"settings","title":"Settings","description":"Settings is accessible from the gear icon at the bottom of the left navigation bar. It has four sections: Resources, Proxy, CLI Tools, and Preferences.","sidebar":"docsSidebar"},"skills-mcp-knowledge":{"id":"skills-mcp-knowledge","title":"Skills, MCP Servers & Knowledge Bases","description":"Beyond the AI model itself, Kaiden agents can be equipped with three types of additional capability: Skills, MCP Servers, and Knowledge Bases. Together they determine what the agent knows and what tools it can use.","sidebar":"docsSidebar"},"what-is-kaiden":{"id":"what-is-kaiden","title":"What is Kaiden?","description":"Kaiden is an open-source tool for managing agentic coding environments. Instead of giving autonomous agents unrestricted access to your machine, Kaiden wraps your preferred coding agents \u2014 Claude Code, Goose, Cursor, and others \u2014 in isolated Podman or MicroVM sandboxes.","sidebar":"docsSidebar"},"your-first-sandbox":{"id":"your-first-sandbox","title":"Your First Sandbox","description":"A sandbox is the secured, persistent environment where an agent actually runs. It combines a project folder, a chosen agent and model, and a set of policies \u2014 what the agent can read on disk, what it can reach on the network, and which credentials it can use.","sidebar":"docsSidebar"}}}}')}}]);